import fs from 'fs';
import fsPromises from 'fs/promises';
import os from 'os';
import path from 'path';
import { createLogger } from '../utils/logger';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import { isPathStrictlyInsideRoot } from '../utils/pathContainment';
import type { BundleFile } from './BundleStore';
import { spawnProcess, type ProcessCommand } from './packageManagerProcess';

const log = createLogger('PrototypeBuildService');

const COPY_EXCLUDE = new Set([
  'node_modules',
  '.git',
  '.vite',
  '.rivet',
  'dist',
  'build',
  '.next',
  '.cache',
]);

export class PrototypeBuildError extends Error {
  constructor(
    message: string,
    readonly detail?: string,
  ) {
    super(message);
    this.name = 'PrototypeBuildError';
  }
}

export interface BuildResult {
  files: BundleFile[];
  totalBytes: number;
}

const INSTALL_TIMEOUT_MS = 180_000;
const BUILD_TIMEOUT_MS = 120_000;

const withStaticEntryBase = (html: string, entryPath: string): string => {
  const entryDir = path.posix.dirname(entryPath);
  if (entryDir === '.' || /<base\s/i.test(html)) return html;
  const baseTag = `<base href="${encodeURI(`./${entryDir}/`)}">`;
  const headMatch = /<head[^>]*>/i.exec(html);
  if (headMatch) {
    const insertAt = headMatch.index + headMatch[0].length;
    return html.slice(0, insertAt) + baseTag + html.slice(insertAt);
  }
  return baseTag + html;
};

export class PrototypeBuildService {
  async build(filesDir: string): Promise<BuildResult> {
    const pkgJson = path.join(filesDir, 'package.json');
    if (!fs.existsSync(pkgJson)) {
      throw new PrototypeBuildError(
        'This prototype has no package.json — only fresh Vite app prototypes can be deployed.',
      );
    }

    const scratch = await fsPromises.mkdtemp(
      path.join(os.tmpdir(), 'rivet-deploy-'),
    );
    try {
      const projectDir = path.join(scratch, 'app');
      await fsPromises.cp(filesDir, projectDir, {
        recursive: true,
        filter: (src) => !COPY_EXCLUDE.has(path.basename(src)),
      });

      const hasLockfile = fs.existsSync(
        path.join(projectDir, 'package-lock.json'),
      );
      await this.runStep(
        {
          packageManager: 'npm',
          args: hasLockfile ? ['ci'] : ['install', '--no-audit', '--no-fund'],
        },
        projectDir,
        INSTALL_TIMEOUT_MS,
        'install dependencies',
      );

      await this.runStep(
        { packageManager: 'npx', args: ['vite', 'build', '--base=./'] },
        projectDir,
        BUILD_TIMEOUT_MS,
        'build the prototype',
      );

      const distDir = path.join(projectDir, 'dist');
      if (!fs.existsSync(path.join(distDir, 'index.html'))) {
        throw new PrototypeBuildError(
          'Build completed but produced no dist/index.html — unable to deploy.',
        );
      }

      return await this.packDir(distDir);
    } finally {
      await fsPromises.rm(scratch, { recursive: true, force: true });
    }
  }

  async packStatic(filesDir: string, entryPath: string): Promise<BuildResult> {
    const rootPath = path.resolve(filesDir);
    const entryFile = path.resolve(rootPath, entryPath);
    if (
      !isPathStrictlyInsideRoot(rootPath, entryFile) ||
      !fs.existsSync(entryFile)
    ) {
      throw new PrototypeBuildError(
        `This prototype has no ${entryPath} to deploy.`,
      );
    }
    const selectedEntryPath = path
      .relative(rootPath, entryFile)
      .split(path.sep)
      .join('/');
    const packed = await this.packDir(filesDir);
    const selectedEntry = packed.files.find(
      (file) => file.path === selectedEntryPath,
    );
    if (!selectedEntry) {
      throw new PrototypeBuildError(
        `This prototype has no ${entryPath} to deploy.`,
      );
    }
    const html = withStaticEntryBase(
      Buffer.from(selectedEntry.content, 'base64').toString('utf8'),
      selectedEntryPath,
    );
    const files = packed.files
      .filter(
        (file) => file.path !== selectedEntryPath && file.path !== 'index.html',
      )
      .concat({
        path: 'index.html',
        content: Buffer.from(html, 'utf8').toString('base64'),
      });
    const totalBytes = files.reduce(
      (total, file) => total + Buffer.from(file.content, 'base64').length,
      0,
    );
    return { files, totalBytes };
  }

  private async packDir(distDir: string): Promise<BuildResult> {
    const files: BundleFile[] = [];
    let totalBytes = 0;
    const walk = async (dir: string, prefix: string): Promise<void> => {
      const entries = await fsPromises.readdir(dir, { withFileTypes: true });
      for (const entry of entries) {
        if (COPY_EXCLUDE.has(entry.name)) continue;
        const abs = path.join(dir, entry.name);
        const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
        if (entry.isDirectory()) {
          await walk(abs, rel);
        } else if (entry.isFile()) {
          const body = await fsPromises.readFile(abs);
          totalBytes += body.length;
          files.push({ path: rel, content: body.toString('base64') });
        }
      }
    };
    await walk(distDir, '');
    return { files, totalBytes };
  }

  private runStep(
    command: ProcessCommand,
    cwd: string,
    timeoutMs: number,
    label: string,
  ): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const proc = spawnProcess(command, {
        cwd,
        env: subprocessEnvironment('packageManager'),
        stdio: ['ignore', 'pipe', 'pipe'],
        detached: false,
      });
      let stderrTail = '';
      const appendTail = (data: Buffer) => {
        stderrTail = (stderrTail + data.toString()).slice(-4_000);
      };
      proc.stdout?.on('data', (d: Buffer) => {
        log.debug(`[deploy-build] ${d.toString().trim()}`);
      });
      proc.stderr?.on('data', (d: Buffer) => {
        appendTail(d);
        log.debug(`[deploy-build] ${d.toString().trim()}`);
      });

      const timer = setTimeout(() => {
        try {
          proc.kill('SIGTERM');
        } catch {
        }
        setTimeout(() => {
          try {
            proc.kill('SIGKILL');
          } catch {
          }
        }, 5_000).unref();
        reject(
          new PrototypeBuildError(
            `Timed out trying to ${label} (after ${Math.round(
              timeoutMs / 1000,
            )}s).`,
            stderrTail.trim(),
          ),
        );
      }, timeoutMs);

      proc.on('error', (err) => {
        clearTimeout(timer);
        reject(
          new PrototypeBuildError(
            `Failed to ${label}: ${err.message}`,
            stderrTail.trim(),
          ),
        );
      });
      proc.on('close', (code) => {
        clearTimeout(timer);
        if (code === 0) {
          resolve();
        } else {
          reject(
            new PrototypeBuildError(
              `Failed to ${label} (exit ${code}).`,
              stderrTail.trim(),
            ),
          );
        }
      });
    });
  }
}
